const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const result = $('Save Link').item.json;
const chatId = $('Telegram Trigger').item.json.message.chat.id;

let text;
if (result.duplicate) {
  const originalText = $('Telegram Trigger').item.json.message.text || '';
  if (originalText.includes('/tag')) return { skipped: true };
  text = '⚠️ هذا الرابط محفوظ من قبل';
} else if (!result.success) {
  text = '❌ فشل الحفظ' + (result.fetchError ? '\n' + result.fetchError : '');
} else if (result.itemType === 'video' && result.contentDepth === 'metadata-only') {
  text = 'حُفظ ✅ — وصف فقط، بدون نص الفيديو\n\n📌 ' + result.title + '\n📁 ' + result.file;
} else if (!result.gotContent) {
  text = 'حُفظ ✅ — الرابط فقط، تعذّر جلب المحتوى\n\n📁 ' + result.file + (result.fetchError ? '\n⚠️ ' + result.fetchError : '');
} else {
  text = 'حُفظ ✅\n\n📌 ' + result.title + '\n📁 ' + result.file;
}

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + config.telegram_bot_token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: { chat_id: chatId, text: text }
});

return { sent: true };

const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

// Parse URL and personal note from message
const fullText = ($('Message buffer').item.json.message?.text || $('Telegram Trigger').item.json.message?.text || '').trim();
const urlMatch = fullText.match(/https?:\/\/[^\s]+/);
if (fullText.includes('/tag')) return [];
const originalUrl = urlMatch[0];
const rawNote = fullText.replace(originalUrl, '').trim();

// Reminder instruction
const remindMatch = rawNote.match(/\/remind\s+(\d+)(day|days|week|weeks|month|months)/i);
let reminderDate = null;
let personalNote = rawNote.replace(/\/remind\s+\S+/i, '').trim();
if (remindMatch) {
  const amount = parseInt(remindMatch[1]);
  const unit = remindMatch[2].toLowerCase();
  const d = new Date();
  if (unit.startsWith('day')) d.setDate(d.getDate() + amount);
  else if (unit.startsWith('week')) d.setDate(d.getDate() + amount * 7);
  else if (unit.startsWith('month')) d.setMonth(d.getMonth() + amount);
  reminderDate = d.toISOString().split('T')[0];
}

// Helper: remember last URL for /tag this
function storeLastUrl() {
  try {
    let buf = {};
    try { buf = JSON.parse(fs.readFileSync(config.message_buffer_file, 'utf8')); } catch(e) {}
    buf[String($('Telegram Trigger').item.json.message.chat.id) + '_last_url'] = originalUrl;
    fs.writeFileSync(config.message_buffer_file, JSON.stringify(buf), 'utf8');
  } catch(e) {}
}

// Duplicate check across all of raw/ (recursive)
function findUrlIn(dir) {
  let entries = [];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch(e) { return false; }
  for (const ent of entries) {
    const p = dir + '/' + ent.name;
    if (ent.isDirectory()) { if (findUrlIn(p)) return true; }
    else if (ent.name.endsWith('.md')) {
      try { if (fs.readFileSync(p, 'utf8').includes(originalUrl)) return true; } catch(e) {}
    }
  }
  return false;
}
if (findUrlIn(config.knowledge_dir + '/raw')) {
  storeLastUrl();
  return { success: false, duplicate: true, message: 'Already saved this link before' };
}

const videoPatterns = ['tiktok.com', 'youtube.com', 'youtu.be', 'instagram.com'];
const isVideo = videoPatterns.some(p => originalUrl.includes(p));
const isTelegram = originalUrl.includes('t.me/');
const isTwitter = originalUrl.includes('x.com') || originalUrl.includes('twitter.com');
const isReddit = originalUrl.includes('reddit.com') || originalUrl.includes('redd.it');

let pageContent = '';
let contentDepth = 'metadata-only';
let fetchError = '';
let pageTitle = '';
let itemType = isVideo ? 'video' : 'link';

// --- Video: deep extraction via ytdlp API (captions, else Whisper) ---
if (isVideo) {
  try {
    const ytResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: config.ytdlp_api_url + '/' + encodeURIComponent(originalUrl),
      timeout: 540000
    });
    pageContent = ytResponse.content || '';
    contentDepth = ytResponse.content_depth || (pageContent ? 'metadata-only' : 'metadata-only');
    pageTitle = ytResponse.title || '';
    if (ytResponse.error) fetchError = String(ytResponse.error);
  } catch(e) {
    fetchError = 'ytdlp API: ' + e.message;
  }
}

// --- X.com via oEmbed ---
if (isTwitter) {
  try {
    const oembedResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://publish.twitter.com/oembed?url=' + encodeURIComponent(originalUrl) + '&omit_script=true',
      timeout: 10000
    });
    const html = oembedResponse.html || '';
    pageContent = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    if (oembedResponse.author_name) pageContent = 'Author: ' + oembedResponse.author_name + ' | ' + pageContent;
    if (pageContent) contentDepth = 'full';
  } catch(e) {
    fetchError = 'oEmbed: ' + e.message;
  }
}

// --- Reddit: info from URL only ---
if (isReddit && !pageContent) {
  const subredditMatch = originalUrl.match(/reddit\.com\/r\/([^\/]+)/);
  const slugMatch = originalUrl.match(/comments\/[^\/]+\/([^\/\?]+)/);
  const subreddit = subredditMatch ? subredditMatch[1] : '';
  const slug = slugMatch ? slugMatch[1].replace(/_/g, ' ') : '';
  pageContent = 'Reddit post' + (subreddit ? ' in r/' + subreddit : '') + (slug ? ': ' + slug : '');
}

// --- Telegram post via Bot API ---
if (isTelegram) {
  try {
    const tgMatch = originalUrl.match(/t\.me\/(?:c\/)?([^\/]+)\/(\d+)/);
    if (tgMatch) {
      const chatId = tgMatch[1].startsWith('c/') ? '-100' + tgMatch[1] : '@' + tgMatch[1];
      const tgResponse = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://api.telegram.org/bot' + config.telegram_bot_token + '/forwardMessage',
        body: { chat_id: config.telegram_chat_id, from_chat_id: chatId, message_id: parseInt(tgMatch[2]) }
      });
      pageContent = tgResponse?.result?.text || tgResponse?.result?.caption || '';
      if (pageContent) contentDepth = 'full';
    }
  } catch(e) {
    fetchError = 'telegram: ' + e.message;
  }
}

// --- Articles/pages: Firecrawl, then raw-HTML fallback ---
if (!isVideo && !isTelegram && !isTwitter && !isReddit) {
  try {
    const crawlResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.firecrawl.dev/v1/scrape',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.firecrawl_api_key },
      body: { url: originalUrl, formats: ['markdown'], onlyMainContent: true },
      timeout: 30000
    });
    pageContent = (crawlResponse?.data?.markdown || crawlResponse?.markdown || '').slice(0, 20000);
    pageTitle = crawlResponse?.data?.metadata?.title || '';
    if (pageContent) contentDepth = 'full';
  } catch(e) {
    fetchError = 'firecrawl: ' + e.message;
  }
  if (!pageContent) {
    // Fallback: plain HTML fetch, strip tags
    try {
      const htmlResp = await this.helpers.httpRequest({
        method: 'GET', url: originalUrl, timeout: 20000,
        headers: { 'User-Agent': 'Mozilla/5.0 (compatible; knowledge-bot)' }
      });
      const html = String(htmlResp || '');
      const titleMatch = html.match(/<title[^>]*>([^<]*)<\/title>/i);
      if (titleMatch) pageTitle = titleMatch[1].trim();
      pageContent = html
        .replace(/<script[\s\S]*?<\/script>/gi, ' ')
        .replace(/<style[\s\S]*?<\/style>/gi, ' ')
        .replace(/<[^>]*>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 20000);
      if (pageContent.length > 200) {
        contentDepth = 'full';
        fetchError = '';
      }
    } catch(e2) {
      fetchError = fetchError + ' | html fallback: ' + e2.message;
    }
  }
}

// --- Write one file per item to raw/inbox (capture is intentionally dumb: no LLM) ---
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = now.getFullYear() + '-' + pad(now.getMonth()+1) + '-' + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
const slugSource = pageTitle || originalUrl.replace(/https?:\/\/(www\.)?/, '');
const slug = slugSource.toLowerCase()
  .replace(/[^a-z0-9؀-ۿ]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'link';

const inboxDir = config.knowledge_dir + '/raw/inbox';
fs.mkdirSync(inboxDir, { recursive: true });
let filename = stamp + '-' + slug + '.md';
let filepath = inboxDir + '/' + filename;
let counter = 1;
while (fs.existsSync(filepath)) {
  filename = stamp + '-' + slug + '-' + (++counter) + '.md';
  filepath = inboxDir + '/' + filename;
}

const fm = [
  '---',
  'agent: ورّاق',
  'captured: ' + now.toISOString(),
  'type: ' + itemType,
  'source: ' + originalUrl,
  'content-depth: ' + contentDepth,
  pageTitle ? 'title: "' + pageTitle.replace(/"/g, "'") + '"' : null,
  fetchError ? 'fetch-error: "' + fetchError.replace(/"/g, "'").slice(0, 200) + '"' : null,
  '---',
].filter(Boolean).join('\n');

const noteSection = personalNote ? '\n**My note:** ' + personalNote + '\n' : '';
const reminderSection = reminderDate ? '\n**Reminder:** ' + reminderDate + '\n' : '';
const body = fm + '\n\n# ' + (pageTitle || originalUrl) + '\n\nSource: ' + originalUrl + '\n' + noteSection + reminderSection + '\n' + (pageContent || '_(no content could be fetched)_') + '\n';

fs.writeFileSync(filepath, body, 'utf8');
storeLastUrl();

return {
  success: true,
  file: 'raw/inbox/' + filename,
  title: pageTitle || originalUrl,
  itemType,
  contentDepth,
  fetchError,
  gotContent: !!pageContent,
  url: originalUrl
};

const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const message = $('Telegram Trigger').item.json.message;
if (!message.voice && !message.audio) return [];

const fileId = message.voice?.file_id || message.audio?.file_id;
const chatId = message.chat.id;

// Get file path from Telegram
const fileInfo = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.telegram.org/bot' + config.telegram_bot_token + '/getFile?file_id=' + fileId
});
const filePath = fileInfo.result.file_path;
const fileUrl = 'https://api.telegram.org/file/bot' + config.telegram_bot_token + '/' + filePath;

// Send to local Whisper API
let text = '';
let transcribeError = '';
try {
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: config.whisper_api_url,
    headers: { 'Content-Type': 'application/json' },
    body: { url: fileUrl, key: config.groq_api_key },
    timeout: 120000
  });
  text = result.text || '';
  if (result.error) transcribeError = String(result.error);
} catch(e) {
  transcribeError = e.message;
}

// Reminder detection in transcribed text
const remindMatch = text.match(/\/remind\s+(\d+)(day|days|week|weeks|month|months)/i);
let reminderDate = null;
let cleanText = text.replace(/\/remind\s+\S+/i, '').trim();
if (remindMatch) {
  const amount = parseInt(remindMatch[1]);
  const unit = remindMatch[2].toLowerCase();
  const d = new Date();
  if (unit.startsWith('day')) d.setDate(d.getDate() + amount);
  else if (unit.startsWith('week')) d.setDate(d.getDate() + amount * 7);
  else if (unit.startsWith('month')) d.setMonth(d.getMonth() + amount);
  reminderDate = d.toISOString().split('T')[0];
}

// One file per item in raw/inbox
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = now.getFullYear() + '-' + pad(now.getMonth()+1) + '-' + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
const slug = (cleanText || 'voice-note').toLowerCase()
  .replace(/[^a-z0-9؀-ۿ]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 40) || 'voice-note';

const inboxDir = config.knowledge_dir + '/raw/inbox';
fs.mkdirSync(inboxDir, { recursive: true });
let filename = stamp + '-voice-' + slug + '.md';
let filepathOut = inboxDir + '/' + filename;
let counter = 1;
while (fs.existsSync(filepathOut)) {
  filename = stamp + '-voice-' + slug + '-' + (++counter) + '.md';
  filepathOut = inboxDir + '/' + filename;
}

const fm = [
  '---',
  'agent: ورّاق',
  'captured: ' + now.toISOString(),
  'type: voice',
  'source: telegram-voice',
  'content-depth: ' + (cleanText ? 'transcript' : 'metadata-only'),
  transcribeError ? 'fetch-error: "' + transcribeError.replace(/"/g, "'").slice(0, 200) + '"' : null,
  '---',
].filter(Boolean).join('\n');

const reminderSection = reminderDate ? '\n**Reminder:** ' + reminderDate + '\n' : '';
const body = fm + '\n\n# 🎤 Voice note — ' + stamp + '\n' + reminderSection + '\n' + (cleanText || '_(transcription failed)_') + '\n';
fs.writeFileSync(filepathOut, body, 'utf8');

return { chatId, text: cleanText, saved: true, file: 'raw/inbox/' + filename, transcribeError };

const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const result = $('Transcribe voice').item.json;
const chatId = result.chatId || $('Telegram Trigger').item.json.message.chat.id;

let text;
if (result.saved && result.text) {
  const preview = result.text.length > 200 ? result.text.slice(0, 200) + '…' : result.text;
  text = 'حُفظ ✅ 🎤\n\n📁 ' + result.file + '\n\n«' + preview + '»';
} else if (result.saved) {
  text = 'حُفظ ✅ — لكن فشل تفريغ الصوت' + (result.transcribeError ? '\n⚠️ ' + result.transcribeError : '');
} else {
  text = '❌ فشل حفظ الملاحظة الصوتية' + (result.transcribeError ? '\n' + result.transcribeError : '');
}

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + config.telegram_bot_token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: { chat_id: chatId, text: text }
});

return { sent: true };

const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const message = $('Telegram Trigger').item.json.message;
if (!message.photo && !message.document?.mime_type?.startsWith('image')) return [];

const chatId = message.chat.id;
const caption = message.caption || '';
const mediaGroupId = message.media_group_id || null;

// Get the photo file from Telegram
const photo = message.photo ? message.photo[message.photo.length - 1] : message.document;
const fileId = photo.file_id;
const fileInfo = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.telegram.org/bot' + config.telegram_bot_token + '/getFile?file_id=' + fileId
});
const filePath = fileInfo.result.file_path;
const fileUrl = 'https://api.telegram.org/file/bot' + config.telegram_bot_token + '/' + filePath;

const imageBuffer = await this.helpers.httpRequest({
  method: 'GET',
  url: fileUrl,
  returnFullResponse: true,
  encoding: 'arraybuffer'
});
const base64Image = Buffer.from(imageBuffer.body).toString('base64');
const mimeType = filePath.endsWith('.png') ? 'image/png' : 'image/jpeg';

// Media-group handling — only first photo of a group creates the note
const groupCachePath = config.knowledge_dir + '/../media_group_cache.json';
let groupCache = {};
try { groupCache = JSON.parse(fs.readFileSync(groupCachePath, 'utf8')); } catch(e) {}
const now0 = Date.now();
Object.keys(groupCache).forEach(k => {
  if (now0 - groupCache[k].timestamp > 30000) delete groupCache[k];
});
if (mediaGroupId && groupCache[mediaGroupId]) {
  groupCache[mediaGroupId].count++;
  fs.writeFileSync(groupCachePath, JSON.stringify(groupCache), 'utf8');
  // still store the extra image file so nothing is lost
  const imagesDirX = config.knowledge_dir + '/raw/images';
  fs.mkdirSync(imagesDirX, { recursive: true });
  const extraName = Date.now() + '.' + (filePath.endsWith('.png') ? 'png' : 'jpg');
  fs.writeFileSync(imagesDirX + '/' + extraName, Buffer.from(imageBuffer.body));
  return { skipped: true, reason: 'already_processed_group', mediaGroupId };
}
if (mediaGroupId) {
  groupCache[mediaGroupId] = { timestamp: now0, count: 1 };
  fs.writeFileSync(groupCachePath, JSON.stringify(groupCache), 'utf8');
  await new Promise(resolve => setTimeout(resolve, 2000));
  try { groupCache = JSON.parse(fs.readFileSync(groupCachePath, 'utf8')); } catch(e) {}
}
const totalInGroup = mediaGroupId ? (groupCache[mediaGroupId]?.count || 1) : 1;

// Vision content description (allowed for capture: describe, never categorize)
let description = '';
let visionError = '';
try {
  const groqResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.groq_api_key },
    body: {
      model: 'meta-llama/llama-4-scout-17b-16e-instruct',
      temperature: 0.1,
      messages: [{
        role: 'user',
        content: [
          { type: 'image_url', image_url: { url: 'data:' + mimeType + ';base64,' + base64Image } },
          { type: 'text', text: 'Describe the content of this image faithfully and completely: what it shows, any visible text (transcribe it exactly, keep Arabic as Arabic), and context. Plain text only, no JSON, no opinions, no categorization.' + (caption ? '\nUser caption: ' + caption : '') + (totalInGroup > 1 ? '\nNote: this is 1 of ' + totalInGroup + ' photos sent together.' : '') }
        ]
      }]
    },
    timeout: 60000
  });
  description = groqResponse.choices?.[0]?.message?.content || '';
} catch(e) {
  visionError = e.message;
}

// Reminder in caption
const remindMatch = caption.match(/\/remind\s+(\d+)(day|days|week|weeks|month|months)/i);
let reminderDate = null;
const cleanCaption = caption.replace(/\/remind\s+\S+/i, '').trim();
if (remindMatch) {
  const amount = parseInt(remindMatch[1]);
  const unit = remindMatch[2].toLowerCase();
  const d = new Date();
  if (unit.startsWith('day')) d.setDate(d.getDate() + amount);
  else if (unit.startsWith('week')) d.setDate(d.getDate() + amount * 7);
  else if (unit.startsWith('month')) d.setMonth(d.getMonth() + amount);
  reminderDate = d.toISOString().split('T')[0];
}

// Store image in raw/images, note in raw/inbox
const imagesDir = config.knowledge_dir + '/raw/images';
fs.mkdirSync(imagesDir, { recursive: true });
const imageFilename = Date.now() + '.' + (filePath.endsWith('.png') ? 'png' : 'jpg');
fs.writeFileSync(imagesDir + '/' + imageFilename, Buffer.from(imageBuffer.body));

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = now.getFullYear() + '-' + pad(now.getMonth()+1) + '-' + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
const slugSource = cleanCaption || 'image';
const slug = slugSource.toLowerCase().replace(/[^a-z0-9؀-ۿ]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'image';

const inboxDir = config.knowledge_dir + '/raw/inbox';
fs.mkdirSync(inboxDir, { recursive: true });
let filename = stamp + '-image-' + slug + '.md';
let filepathOut = inboxDir + '/' + filename;
let counter = 1;
while (fs.existsSync(filepathOut)) {
  filename = stamp + '-image-' + slug + '-' + (++counter) + '.md';
  filepathOut = inboxDir + '/' + filename;
}

const fm = [
  '---',
  'agent: ورّاق',
  'captured: ' + now.toISOString(),
  'type: image',
  'source: telegram-image',
  'content-depth: ' + (description ? 'transcript' : 'metadata-only'),
  'image: raw/images/' + imageFilename,
  visionError ? 'fetch-error: "' + visionError.replace(/"/g, "'").slice(0, 200) + '"' : null,
  '---',
].filter(Boolean).join('\n');

const reminderSection = reminderDate ? '\n**Reminder:** ' + reminderDate + '\n' : '';
const groupNote = totalInGroup > 1 ? '\n**Part of group:** ' + totalInGroup + ' photos\n' : '';
const body = fm + '\n\n# 🖼 ' + (cleanCaption || 'Image — ' + stamp) + '\n\n![[' + 'raw/images/' + imageFilename + ']]\n' + (cleanCaption ? '\n**Caption:** ' + cleanCaption + '\n' : '') + groupNote + reminderSection + '\n' + (description || '_(no description available)_') + '\n';
fs.writeFileSync(filepathOut, body, 'utf8');

return {
  chatId,
  saved: true,
  file: 'raw/inbox/' + filename,
  image: imageFilename,
  totalInGroup,
  mediaGroupId,
  visionError,
  gotDescription: !!description
};

const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const result = $('Save image').item.json;
if (result.skipped) return { skipped: true };

const chatId = result.chatId || $('Telegram Trigger').item.json.message.chat.id;

let text;
if (result.saved && result.gotDescription) {
  text = 'حُفظ ✅ 🖼\n\n📁 ' + result.file + (result.totalInGroup > 1 ? '\n📷 ' + result.totalInGroup + ' صور في المجموعة' : '');
} else if (result.saved) {
  text = 'حُفظ ✅ 🖼 — الصورة فقط، فشل وصف المحتوى' + (result.visionError ? '\n⚠️ ' + result.visionError : '');
} else {
  text = '❌ فشل حفظ الصورة';
}

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + config.telegram_bot_token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: { chat_id: chatId, text: text }
});

return { sent: true };

const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const message = $('Telegram Trigger').item.json.message;
if (!message || !message.text) return [];
let question = message.text.trim();
const senderId = String(message.from?.id || '');
const chatId = String(message.chat?.id || '');

// ============================================
// Handle "/tag this" — look up last saved URL for this chat
// ============================================
if (question.toLowerCase().startsWith('/tag') && /\bthis\b/i.test(question)) {
  let lastUrl = null;
  // First try buffer
  try {
    const buf = JSON.parse(fs.readFileSync(config.message_buffer_file, 'utf8'));
    lastUrl = buf[chatId + '_last_url'];
  } catch(e) {}
  // Fallback: find most recently saved entry across all files
  if (!lastUrl) {
    try {
      const files = fs.readdirSync(config.knowledge_dir).filter(f => f.endsWith('.md'));
      let latestDate = '';
      let latestUrl = '';
      for (const file of files) {
        const content = fs.readFileSync(config.knowledge_dir + '/' + file, 'utf8');
        const entries = content.split('---').filter(e => e.trim() && e.includes('##'));
        for (const entry of entries) {
          const dateMatch = entry.match(/\*\*Saved:\*\* (\d{4}-\d{2}-\d{2})/);
          const urlMatch = entry.match(/## \[.+?\]\((.+?)\)/);
          if (dateMatch && urlMatch && dateMatch[1] >= latestDate) {
            latestDate = dateMatch[1];
            latestUrl = urlMatch[1];
          }
        }
      }
      if (latestUrl) lastUrl = latestUrl;
    } catch(e) {}
  }
  if (lastUrl) {
    question = question.replace(/\bthis\b/i, lastUrl);
  }
}

// ============================================
// Guest access helpers
// ============================================
function loadGuests() {
  try { return JSON.parse(fs.readFileSync(config.guests_file, 'utf8')); } catch(e) { return []; }
}
function saveGuests(guests) {
  fs.writeFileSync(config.guests_file, JSON.stringify(guests, null, 2), 'utf8');
}
function isOwner() {
  return senderId === String(config.telegram_chat_id);
}
function getGuest() {
  const guests = loadGuests();
  const today = new Date().toISOString().split('T')[0];
  return guests.find(g => String(g.telegram_id) === senderId && g.expires >= today) || null;
}

// ============================================
// Owner-only commands
// ============================================
if (isOwner()) {

  if (question.startsWith('http')) return [];

  // /invite command
  if (question.toLowerCase().startsWith('/invite')) {
    const parts = question.split(' ');
    if (parts.length < 4) {
      return { answer: 'Usage: /invite <telegram_id> <categories> <duration>\nExample: /invite 123456789 travel,food 7days\nDuration: 1day, 7days, 30days, permanent' };
    }
    const guestId = parts[1];
    const categories = parts[2].toLowerCase().split(',').map(c => c.trim().replace(/[^a-z0-9]/g, ''));
    const durationStr = parts[3].toLowerCase();
    let expires;
    if (durationStr === 'permanent') {
      expires = '9999-12-31';
    } else {
      const amount = parseInt(durationStr);
      const unit = durationStr.replace(/[0-9]/g, '');
      const d = new Date();
      if (unit.startsWith('day')) d.setDate(d.getDate() + amount);
      else if (unit.startsWith('week')) d.setDate(d.getDate() + amount * 7);
      else if (unit.startsWith('month')) d.setMonth(d.getMonth() + amount);
      expires = d.toISOString().split('T')[0];
    }
    const guests = loadGuests();
    const existingIdx = guests.findIndex(g => String(g.telegram_id) === guestId);
    const newGuest = { telegram_id: guestId, categories, expires, added: new Date().toISOString().split('T')[0] };
    if (existingIdx >= 0) guests[existingIdx] = newGuest; else guests.push(newGuest);
    saveGuests(guests);
    return { answer: '✅ Guest access granted\n\nID: ' + guestId + '\nCategories: ' + categories.join(', ') + '\nExpires: ' + expires };
  }

  // /guests command
  if (question.toLowerCase().startsWith('/guests')) {
    const guests = loadGuests();
    const today = new Date().toISOString().split('T')[0];
    const active = guests.filter(g => g.expires >= today);
    if (active.length === 0) return { answer: 'No active guests.' };
    const list = active.map((g, i) =>
      `${i + 1}. ID: ${g.telegram_id}\n   Categories: ${g.categories.join(', ')}\n   Expires: ${g.expires}`
    ).join('\n\n');
    return { answer: '👥 Active guests (' + active.length + '):\n\n' + list };
  }

  // /revoke command
  if (question.toLowerCase().startsWith('/revoke')) {
    const guestId = question.split(' ')[1];
    if (!guestId) return { answer: 'Usage: /revoke <telegram_id>' };
    let guests = loadGuests();
    const before = guests.length;
    guests = guests.filter(g => String(g.telegram_id) !== guestId);
    saveGuests(guests);
    return { answer: before > guests.length ? '✅ Access revoked for ' + guestId : '❌ Guest not found: ' + guestId };
  }

  // /list command
  if (question.toLowerCase().startsWith('/list') || question.toLowerCase().startsWith('list ')) {
    const listCategory = question.toLowerCase().replace(/^\/?list\s+/, '').replace(/[^a-z0-9]/g, '');
    if (!listCategory) return { answer: 'Usage: /list <category>\nExample: /list travel' };
    const filepath = config.knowledge_dir + '/' + listCategory + '.md';
    try {
      const content = fs.readFileSync(filepath, 'utf8');
      const entries = content.split('---').filter(e => e.trim() && e.includes('##'));
      if (entries.length === 0) return { answer: 'No saved links in category: ' + listCategory };
      const list = entries.map((e, i) => {
        const titleMatch = e.match(/## \[(.+?)\]\((.+?)\)/);
        const dateMatch = e.match(/\*\*Saved:\*\* (.+)/);
        if (titleMatch) return `${i + 1}. ${titleMatch[1]}\n${titleMatch[2]}\n📅 ${dateMatch?.[1] || ''}`;
        return null;
      }).filter(Boolean).join('\n\n');
      return { answer: `📂 ${listCategory} — ${entries.length} saved links\n\n${list}` };
    } catch(e) {
      return { answer: 'No saved links in category: ' + listCategory };
    }
  }

  // /tag command
  if (question.toLowerCase().startsWith('/tag')) {
    const urlMatch = question.match(/https?:\/\/[^\s]+/);
    const tagMatches = question.match(/#[\w_]+/g);
    if (!urlMatch) return { answer: 'Usage: /tag <url> #tag1 #tag2\nTip: You can also use "/tag this #tag" right after saving a link' };
    const targetUrl = urlMatch[0];
    const userTags = tagMatches ? tagMatches.join(' ') : '';
    try {
      const files = fs.readdirSync(config.knowledge_dir).filter(f => f.endsWith('.md'));
      for (const file of files) {
        const filepath = config.knowledge_dir + '/' + file;
        let content = fs.readFileSync(filepath, 'utf8');
        if (content.includes(targetUrl)) {
          if (userTags) {
            content = content.replace(
              /(## \[.+?\]\(.+?\)[\s\S]*?\*\*Tags:\*\* )([^\n]+)/,
              (match, prefix, existingTags) => {
                const existing = existingTags.trim();
                const newTagsToAdd = (tagMatches || []).filter(t => !existing.includes(t)).join(' ');
                return prefix + existing + (newTagsToAdd ? ' ' + newTagsToAdd : '');
              }
            );
            fs.writeFileSync(filepath, content, 'utf8');
          }
          return { answer: '✅ Tags added to existing entry: ' + userTags };
        }
      }
    } catch(e) {}
    let pageContent = '';
    const isVideo = ['tiktok.com','youtube.com','youtu.be','instagram.com'].some(p => targetUrl.includes(p));
    const isTwitter = targetUrl.includes('x.com') || targetUrl.includes('twitter.com');
    if (isVideo) {
      try {
        const ytResponse = await this.helpers.httpRequest({ method: 'GET', url: config.ytdlp_api_url + '/' + encodeURIComponent(targetUrl), timeout: 35000 });
        pageContent = ytResponse.content || '';
      } catch(e) {}
    } else if (isTwitter) {
      try {
        const oembedResponse = await this.helpers.httpRequest({ method: 'GET', url: 'https://publish.twitter.com/oembed?url=' + encodeURIComponent(targetUrl) + '&omit_script=true', timeout: 10000 });
        const html = oembedResponse.html || '';
        pageContent = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
        if (oembedResponse.author_name) pageContent = 'Author: ' + oembedResponse.author_name + ' | ' + pageContent;
      } catch(e) {}
    } else {
      try {
        const crawlResponse = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.firecrawl.dev/v1/scrape', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.firecrawl_api_key }, body: { url: targetUrl, formats: ['markdown'], onlyMainContent: true }, timeout: 30000 });
        pageContent = (crawlResponse?.data?.markdown || '').slice(0, 3000);
      } catch(e) { pageContent = 'Could not fetch page.'; }
    }
    const tagGroqResponse = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.groq.com/openai/v1/chat/completions',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.groq_api_key },
      body: { model: 'llama-3.3-70b-versatile', temperature: 0.1, messages: [
        { role: 'system', content: 'You are a personal knowledge capture assistant. Return structured JSON only.' },
        { role: 'user', content: 'Analyze this link.\n\nURL: ' + targetUrl + '\nUser tags: ' + userTags + '\nPage content: ' + pageContent + '\n\nReturn JSON:\n{"title": "descriptive title", "summary": "2-3 sentence summary", "tags": ["tag1", "tag2", "tag3"], "category": "single lowercase word"}' }
      ]}
    });
    const tagRaw = tagGroqResponse.choices?.[0]?.message?.content || '';
    let tagParsed;
    try { const match = tagRaw.match(/\{[\s\S]*\}/); tagParsed = JSON.parse(match ? match[0] : tagRaw); }
    catch(e) { tagParsed = { title: 'Saved link', summary: targetUrl, tags: [], category: 'misc' }; }
    const tagCategory = (tagParsed.category || 'misc').toLowerCase().replace(/[^a-z0-9]/g, '') || 'misc';
    const groqTags = (tagParsed.tags || []).map(t => '#' + t.toLowerCase().replace(/[\s-]+/g, '_'));
    const allTags = [...new Set([...(tagMatches || []), ...groqTags])].join(' ');
    const tagDate = new Date().toISOString().split('T')[0];
    const tagEntry = '\n## [' + tagParsed.title + '](' + targetUrl + ')\n**Saved:** ' + tagDate + '\n**Tags:** ' + allTags + '\n> ' + tagParsed.summary + '\n\n---\n';
    const tagFilepath = config.knowledge_dir + '/' + tagCategory + '.md';
    if (!fs.existsSync(tagFilepath)) fs.writeFileSync(tagFilepath, '# ' + tagCategory + '\n', 'utf8');
    fs.appendFileSync(tagFilepath, tagEntry, 'utf8');
    return { answer: '✅ Saved to ' + tagCategory + ' with tags: ' + allTags + '\n\n📌 ' + tagParsed.title + '\n' + tagParsed.summary };
  }

  // /rules command
  if (question.toLowerCase().startsWith('/rules')) {
    const rulesText = question.replace(/^\/rules\s*/i, '').trim();
    if (!rulesText) {
      try {
        const rules = JSON.parse(fs.readFileSync(config.knowledge_dir + '/../rules.json', 'utf8'));
        if (rules.length === 0) return { answer: 'No rules set yet.\n\nUsage: /rules if mentions <keyword> then category=<cat> tags=#tag1 #tag2' };
        const rulesList = rules.map((r, i) => `${i + 1}. If mentions "${r.keyword}" → category: ${r.category}, tags: ${r.tags.join(' ')}`).join('\n');
        return { answer: '📋 Current rules:\n\n' + rulesList + '\n\nTo add: /rules if mentions <keyword> then category=<cat> tags=#tag1 #tag2\nTo clear: /rules clear' };
      } catch(e) { return { answer: 'No rules set yet.\n\nUsage: /rules if mentions <keyword> then category=<cat> tags=#tag1 #tag2' }; }
    }
    if (rulesText === 'clear') { fs.writeFileSync(config.knowledge_dir + '/../rules.json', '[]', 'utf8'); return { answer: '✅ All rules cleared' }; }
    const keywordMatch = rulesText.match(/if mentions ([^\s]+)/i);
    const categoryMatch = rulesText.match(/category=([^\s]+)/i);
    const tagsMatch = rulesText.match(/tags=(#[\w_ #]+)/i) || rulesText.match(/(#[\w_]+(?:\s+#[\w_]+)*)/);
    if (!keywordMatch || !categoryMatch) return { answer: 'Format: /rules if mentions <keyword> then category=<cat> tags=#tag1 #tag2' };
    const newRule = { keyword: keywordMatch[1].toLowerCase(), category: categoryMatch[1].toLowerCase().replace(/[^a-z0-9]/g, ''), tags: tagsMatch ? tagsMatch[1].match(/#[\w_]+/g) || [] : [] };
    let rules = [];
    try { rules = JSON.parse(fs.readFileSync(config.knowledge_dir + '/../rules.json', 'utf8')); } catch(e) {}
    const exists = rules.findIndex(r => r.keyword === newRule.keyword);
    if (exists >= 0) rules[exists] = newRule; else rules.push(newRule);
    fs.writeFileSync(config.knowledge_dir + '/../rules.json', JSON.stringify(rules, null, 2), 'utf8');
    return { answer: '✅ Rule saved: if mentions "' + newRule.keyword + '" → category: ' + newRule.category + ', tags: ' + newRule.tags.join(' ') };
  }

  // /rescan command
  if (question.toLowerCase().startsWith('/rescan')) {
    let rules = [];
    try { rules = JSON.parse(fs.readFileSync(config.knowledge_dir + '/../rules.json', 'utf8')); } catch(e) {}
    if (rules.length === 0) return { answer: '⚠️ No rules set. Add rules first with /rules command.' };
    let updatedCount = 0, movedCount = 0;
    try {
      const files = fs.readdirSync(config.knowledge_dir).filter(f => f.endsWith('.md'));
      for (const file of files) {
        const filepath = config.knowledge_dir + '/' + file;
        let content = fs.readFileSync(filepath, 'utf8');
        const originalContent = content;
        for (const rule of rules) {
          const entries = content.split('---');
          const updatedEntries = entries.map(entry => {
            if (!entry.includes('##')) return entry;
            if (!entry.toLowerCase().includes(rule.keyword)) return entry;
            let updated = entry;
            for (const tag of rule.tags) {
              if (!updated.includes(tag)) { updated = updated.replace(/(\*\*Tags:\*\* [^\n]+)/, '$1 ' + tag); updatedCount++; }
            }
            const currentCategory = file.replace('.md', '');
            if (rule.category !== currentCategory) {
              const targetFilepath = config.knowledge_dir + '/' + rule.category + '.md';
              if (!fs.existsSync(targetFilepath)) fs.writeFileSync(targetFilepath, '# ' + rule.category + '\n', 'utf8');
              fs.appendFileSync(targetFilepath, updated + '---\n', 'utf8');
              movedCount++;
              return null;
            }
            return updated;
          });
          content = updatedEntries.filter(e => e !== null).join('---');
        }
        if (content !== originalContent) fs.writeFileSync(filepath, content, 'utf8');
      }
    } catch(e) { return { answer: '❌ Error during rescan: ' + e.message }; }
    return { answer: `✅ Rescan complete\n\n🏷 Tags updated: ${updatedCount}\n📂 Entries moved: ${movedCount}` };
  }

  // /digest command
  if (question.toLowerCase().startsWith('/digest')) {
    const args = question.replace(/^\/digest\s*/i, '').trim().toLowerCase();
    let settings = { enabled: true, time: '09:00', summary: true, categories: true, voice: true, images: true, stats: true, motivation: true };
    try { settings = { ...settings, ...JSON.parse(fs.readFileSync(config.digest_settings_file, 'utf8')) }; } catch(e) {}
    if (!args) {
      const status = s => s ? '✅ on' : '❌ off';
      return { answer: `⚙️ Daily Digest Settings\n\nEnabled: ${status(settings.enabled)}\nTime: ${settings.time}\n\nSummaries: ${status(settings.summary)}\nGroup by category: ${status(settings.categories)}\nVoice notes: ${status(settings.voice)}\nImages: ${status(settings.images)}\nStats comparison: ${status(settings.stats)}\nMotivation: ${status(settings.motivation)}\n\nCommands:\n/digest on|off\n/digest summary on|off\n/digest categories on|off\n/digest voice on|off\n/digest images on|off\n/digest stats on|off\n/digest motivation on|off\n/digest time HH:MM` };
    }
    const parts = args.split(' ');
    const setting = parts[0];
    const value = parts[1];
    if (setting === 'on') { settings.enabled = true; }
    else if (setting === 'off') { settings.enabled = false; }
    else if (setting === 'time' && value) {
      if (value.match(/^\d{1,2}:\d{2}$/)) { settings.time = value; }
      else return { answer: '❌ Invalid time format. Use HH:MM (e.g. /digest time 08:30)' };
    } else if (['summary','categories','voice','images','stats','motivation'].includes(setting)) {
      if (value === 'on') settings[setting] = true;
      else if (value === 'off') settings[setting] = false;
      else return { answer: '❌ Use on or off. Example: /digest summary on' };
    } else {
      return { answer: '❌ Unknown setting. Send /digest to see all options.' };
    }
    fs.writeFileSync(config.digest_settings_file, JSON.stringify(settings, null, 2), 'utf8');
    const changed = setting === 'on' ? 'Digest enabled' : setting === 'off' ? 'Digest paused' : setting === 'time' ? 'Digest time set to ' + value : setting + ' ' + value;
    return { answer: '✅ ' + changed + '\n\nSend /digest to see all settings.' };
  }

  // /help command
  if (question.toLowerCase().startsWith('/help')) {
    return { answer: `📖 Available Commands\n\n🔗 *Saving*\nJust send a URL to save it\n/tag <url> #tag1 #tag2 — save with tags\n/tag this #tag — tag the last saved link\n\n📂 *Browsing*\n/list <category> — list saved links\n\n🏷 *Organization*\n/rules — manage auto-categorization rules\n/rescan — apply rules to all entries\n/suggest — AI reorganization suggestions\n\n⏰ *Reminders*\nAdd /remind 2weeks to any link when saving\n\n📊 *Digest*\n/digest — configure daily digest\n\n👥 *Guest Access*\n/invite <id> <categories> <duration>\n/guests — list active guests\n/revoke <id> — remove guest\n\n💡 *Tips*\n• Send a voice note to save transcription\n• Send an image to save with AI description\n• Add a note after any URL: https://... this is for kitchen\n• Forward any message with a link to save it\n• Share a link then send "/tag this #tag" to tag it` };
  }

  // /suggest command
  if (question.toLowerCase().startsWith('/suggest')) {
    const instruction = question.replace(/^\/suggest\s*/i, '').trim();
    if (!instruction) {
      return { answer: 'Usage: /suggest <your instruction>\n\nExample:\n/suggest anything about AI tools and agents should go to ai category with #agents #tools tags\n\nAfter reviewing suggestions, run /suggest apply to apply them.' };
    }
    if (instruction === 'apply') {
      try {
        const pending = JSON.parse(fs.readFileSync(config.knowledge_dir + '/../pending_suggestions.json', 'utf8'));
        if (pending.length === 0) return { answer: 'No pending suggestions to apply.' };
        let appliedCount = 0;
        for (const s of pending) {
          try {
            const filepath = config.knowledge_dir + '/' + s.currentCategory + '.md';
            let content = fs.readFileSync(filepath, 'utf8');
            if (!content.includes(s.url)) continue;
            if (s.addTags && s.addTags.length > 0) {
              content = content.replace(
                new RegExp(`(## \\[.+?\\]\\(${s.url.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\)[\\s\\S]*?\\*\\*Tags:\\*\\* )([^\\n]+)`),
                (match, prefix, existingTags) => {
                  const existing = existingTags.trim();
                  const newTags = s.addTags.filter(t => !existing.includes(t)).join(' ');
                  return prefix + existing + (newTags ? ' ' + newTags : '');
                }
              );
              fs.writeFileSync(filepath, content, 'utf8');
            }
            if (s.newCategory && s.newCategory !== s.currentCategory) {
              const entryMatch = content.match(new RegExp(`\\n## \\[.+?\\]\\(${s.url.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\)[\\s\\S]*?---`));
              if (entryMatch) {
                const targetFilepath = config.knowledge_dir + '/' + s.newCategory + '.md';
                if (!fs.existsSync(targetFilepath)) fs.writeFileSync(targetFilepath, '# ' + s.newCategory + '\n', 'utf8');
                fs.appendFileSync(targetFilepath, entryMatch[0] + '\n', 'utf8');
                content = content.replace(entryMatch[0], '');
                fs.writeFileSync(filepath, content, 'utf8');
              }
            }
            appliedCount++;
          } catch(e) {}
        }
        fs.writeFileSync(config.knowledge_dir + '/../pending_suggestions.json', '[]', 'utf8');
        return { answer: '✅ Applied ' + appliedCount + ' suggestions successfully.' };
      } catch(e) {
        return { answer: '❌ No pending suggestions found. Run /suggest <instruction> first.' };
      }
    }
    let allEntries = [];
    try {
      const files = fs.readdirSync(config.knowledge_dir).filter(f => f.endsWith('.md'));
      for (const file of files) {
        const content = fs.readFileSync(config.knowledge_dir + '/' + file, 'utf8');
        const category = file.replace('.md', '');
        const entries = content.split('---').filter(e => e.trim() && e.includes('##'));
        for (const entry of entries) {
          const titleMatch = entry.match(/## \[(.+?)\]\((.+?)\)/);
          const tagsMatch = entry.match(/\*\*Tags:\*\* ([^\n]+)/);
          const summaryMatch = entry.match(/> (.+)/);
          if (titleMatch) {
            allEntries.push({ title: titleMatch[1], url: titleMatch[2], category, tags: tagsMatch?.[1] || '', summary: summaryMatch?.[1] || '' });
          }
        }
      }
    } catch(e) {}
    if (allEntries.length === 0) return { answer: 'No saved entries found.' };
    const suggestResponse = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.groq.com/openai/v1/chat/completions',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.groq_api_key },
      body: { model: 'llama-3.3-70b-versatile', temperature: 0.1, messages: [
        { role: 'system', content: 'You are a knowledge organization assistant. Return ONLY a JSON array, no markdown.' },
        { role: 'user', content: 'User instruction: ' + instruction + '\n\nSaved entries:\n' + JSON.stringify(allEntries.slice(0, 50), null, 2) + '\n\nReturn a JSON array: [{"title":"...","url":"...","currentCategory":"...","newCategory":"..." or null,"addTags":["#tag1"] or [],"reason":"short reason"}]\n\nOnly include entries needing changes. Return [] if nothing needs changing.' }
      ]}
    });
    const raw = suggestResponse.choices?.[0]?.message?.content || '[]';
    let suggestions = [];
    try { const match = raw.match(/\[[\s\S]*\]/); suggestions = JSON.parse(match ? match[0] : '[]'); } catch(e) { suggestions = []; }
    if (suggestions.length === 0) return { answer: '✅ No changes needed based on your instruction.' };
    fs.writeFileSync(config.knowledge_dir + '/../pending_suggestions.json', JSON.stringify(suggestions, null, 2), 'utf8');
    const display = suggestions.slice(0, 10).map((s, i) => {
      let line = `${i + 1}. *${s.title}*`;
      if (s.newCategory && s.newCategory !== s.currentCategory) line += `\n   📂 ${s.currentCategory} → ${s.newCategory}`;
      if (s.addTags && s.addTags.length > 0) line += `\n   🏷 Add: ${s.addTags.join(' ')}`;
      line += `\n   💡 ${s.reason}`;
      return line;
    }).join('\n\n');
    const total = suggestions.length;
    return { answer: `🔍 Found ${total} suggestion${total > 1 ? 's' : ''}:\n\n${display}${total > 10 ? '\n\n...and ' + (total - 10) + ' more' : ''}\n\nSend /suggest apply to apply all changes.` };
  }

  // Handle greetings for owner
  const greetings = ['hi','hello','hey','مرحبا','هلا','السلام','صباح','مساء'];
  if (greetings.some(g => question.toLowerCase().startsWith(g))) {
    return { answer: 'أهلاً! أرسل لي رابط لحفظه، أو اسألني عن شيء حفظته سابقاً 👋' };
  }

  // Owner full knowledge query
  const dir = config.knowledge_dir;
  let knowledge = '';
  let fileCount = 0;
  try {
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.md'));
    fileCount = files.length;
    for (const file of files) {
      try {
        const content = fs.readFileSync(dir + '/' + file, 'utf8');
        if (content.trim()) knowledge += '\n\n=== ' + file.replace('.md', '') + ' ===\n' + content.slice(0, 2000);
      } catch(e) {}
    }
  } catch(e) {}
  if (!knowledge.trim()) knowledge = 'No saved links yet.';
  else knowledge = knowledge.slice(0, 20000);

  const groqResponse = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.groq_api_key },
    body: { model: 'llama-3.3-70b-versatile', temperature: 0.2, messages: [
      { role: 'system', content: 'You are a personal knowledge assistant. Answer questions using only the saved links provided. Be concise and helpful. For each relevant item include the title and URL. If nothing matches, say so clearly. Respond in the same language as the question.' },
      { role: 'user', content: 'My saved links (' + fileCount + ' categories):\n' + knowledge + '\n\nQuestion: ' + question }
    ]}
  });
  return { answer: groqResponse.choices?.[0]?.message?.content || 'Could not get an answer.' };
}

// ============================================
// Guest access flow
// ============================================
