const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/home/node/config.json', 'utf8'));

const message = $('Telegram Trigger').item.json.message;
const chatId = String(message.chat.id);
const text = (message.text || message.caption || '').trim();
const messageId = message.message_id;
const now = Date.now();

// Buffer file path
const bufferPath = config.message_buffer_file;
let buffer = {};
try { buffer = JSON.parse(fs.readFileSync(bufferPath, 'utf8')); } catch(e) {}

// Clean old buffer entries (older than 5 seconds)
Object.keys(buffer).forEach(k => {
  if (now - buffer[k].timestamp > 8000) delete buffer[k];
});

// Check if there's a pending message from same chat
if (buffer[chatId]) {
  const prev = buffer[chatId];

  // Handle "/tag this..." pattern — replace "this" with the URL from previous message
  const prevUrl = prev.text.match(/https?:\/\/[^\s]+/)?.[0];
  const isTagThis = text.toLowerCase().startsWith('/tag') && /\bthis\b/i.test(text);
  const isTagWithUrl = text.toLowerCase().startsWith('/tag') && text.match(/https?:\/\//);
  const prevIsUrl = prev.text.match(/^https?:\/\/[^\s]+$/);

  let combined;

  if (prevUrl && isTagThis) {
    // "/tag this #tags" + previous URL → "/tag URL #tags"
    combined = text.replace(/\bthis\b/i, prevUrl);
  } else if (prevIsUrl && text.startsWith('/tag')) {
    // Previous was pure URL, current is /tag command
    const tags = text.match(/#[\w_]+/g) || [];
    combined = '/tag ' + prevUrl + (tags.length ? ' ' + tags.join(' ') : '');
  } else if (prevIsUrl && text.match(/#[\w_]+/)) {
    // Previous was pure URL, current is just hashtags
    const tags = text.match(/#[\w_]+/g) || [];
    combined = '/tag ' + prevUrl + ' ' + tags.join(' ');
  } else {
    // Default: just combine
    combined = prev.text + ' ' + text;
  }

  delete buffer[chatId];
  fs.writeFileSync(bufferPath, JSON.stringify(buffer), 'utf8');
  return { message: { ...message, text: combined.trim() } };
}

// No pending message — store this one and wait
buffer[chatId] = { text, messageId, timestamp: now };
fs.writeFileSync(bufferPath, JSON.stringify(buffer), 'utf8');

// Re-read buffer
try { buffer = JSON.parse(fs.readFileSync(bufferPath, 'utf8')); } catch(e) {}

// If our entry is still there (no follow-up came), process it alone
if (buffer[chatId] && buffer[chatId].messageId === messageId) {
  delete buffer[chatId];
  fs.writeFileSync(bufferPath, JSON.stringify(buffer), 'utf8');
  return { message: { ...message, text: text } };
}

// Another message already combined with ours — skip this one
return [];
